32	/// Der autoritative Mess-POD (16+6). Reine numerische Felder; String-Identität (permutation_id/workload_used)
33	/// wird bei der Serialisierung beigestellt (POD bleibt trivial-kopierbar/ABI-tauglich).
34	struct ComdareMeasurementSnapshotV1 {
35	    static constexpr std::uint32_t kVersion = 1;
36	
37	    // ── Meta (3 der 16) ───────────────────────────────────────────────────────
38	    std::uint64_t fingerprint = 0; // FNV-1a über permutation_id (stabile Zeilen-Identität)
39	    std::uint8_t  succeeded   = 1;
40	    std::uint64_t op_count    = 0;
41	    // ── Performance (1 der 16) ────────────────────────────────────────────────
42	    std::uint64_t total_cycles = 0; // repräsentative Latenz (ns), Stufe-05-Konvention
43	    // ── 6 HW-Counter (6 der 16) — nur gültig wenn pmc_available==1 ─────────────
44	    std::uint64_t cache_misses_l1         = 0;
45	    std::uint64_t cache_misses_l2         = 0;
46	    std::uint64_t cache_misses_l3         = 0;
47	    std::uint64_t dtlb_misses             = 0;
48	    std::uint64_t coherence_invalidations = 0;
49	    std::uint64_t energy_micro_joules     = 0;
50	    std::uint8_t  pmc_available           = 0; // 0 = HW-Counter NICHT real gemessen (P4-gated, ehrlich)
51	    // ── Allocator (4 der 16) — real aus dem Observer ──────────────────────────
52	    std::uint64_t bytes_allocated     = 0;
53	    std::uint64_t bytes_in_use_peak   = 0;
54	    std::uint64_t external_frag_milli = 0; // Fragmentierung in ‰ (Promille), 0 wenn unbekannt
55	    std::uint64_t internal_frag_milli = 0;
56	    // ── 6 funktionale Observer-Spalten (die „+6") ─────────────────────────────
57	    std::uint64_t search_insert         = 0;
58	    std::uint64_t search_lookup         = 0;
59	    std::uint64_t search_hit            = 0;
60	    std::uint64_t search_miss           = 0;
61	    std::uint64_t search_erase          = 0;
62	    std::uint64_t search_peak_occupancy = 0;
63	    // Additive Host-Messspalten (nur volle CSV, NICHT pipeline16).
64	    std::uint64_t branch_misses          = 0;
65	    double        throughput_ops_per_sec = 0.0;
66	};
