117	/// Wie oben, aber befüllt zusätzlich die 6 HW-Counter aus einer PMC-Quelle (#26). `pmc_available` spiegelt
118	/// EHRLICH `pmc.available`: NullPmcSource → 0 (HW-Spalten bleiben 0), reale Quelle → 1 + echte Werte.
119	[[nodiscard]] inline ComdareMeasurementSnapshotV1
120	measurement_from_workload_result(workload_driver::WorkloadRunResult const& r, std::string_view permutation_id,
121	                                 PmcCounters const& pmc) {
122	    auto m = measurement_from_workload_result(r, permutation_id);
123	    if (pmc.available) {
124	        m.cache_misses_l1         = pmc.cache_misses_l1;
125	        m.cache_misses_l2         = pmc.cache_misses_l2;
126	        m.cache_misses_l3         = pmc.cache_misses_l3;
127	        m.dtlb_misses             = pmc.dtlb_misses;
128	        m.branch_misses           = pmc.branch_misses;
129	        m.coherence_invalidations = pmc.coherence_invalidations;
130	        m.energy_micro_joules     = pmc.energy_micro_joules;
131	        m.pmc_available           = 1;
132	    }
133	    return m;
134	}
