136	/// Kanonischer Serializer (das EINE Mess-Schema). Schreibt die 16 Pipeline-kanonischen Spalten (kompatibel
137	/// zur LaTeX-Pipeline-Stufe 04/05/06) PLUS die 6 Observer-Spalten + pmc_available — die volle 16+6-Sicht.
138	/// `rows[i]` ↔ `permutation_ids[i]` ↔ `workload_used[i]` (gleiche Länge). Eine Zeile je (Komposition×Lastprofil).
139	[[nodiscard]] inline std::string serialize_measurements_csv(std::vector<ComdareMeasurementSnapshotV1> const& rows,
140	                                                            std::vector<std::string> const& permutation_ids,
141	                                                            std::vector<std::string> const& workload_used) {
142	    std::ostringstream os;
143	    // 16 Pipeline-kanonische Spalten (Stufe-04/05-konsumierbar) ...
144	    os << "permutation_id,fingerprint,succeeded,workload_used,op_count,total_cycles,"
145	          "cache_misses_l1,cache_misses_l2,cache_misses_l3,dtlb_misses,"
146	          "coherence_invalidations,energy_micro_joules,"
147	          "bytes_allocated,bytes_in_use_peak,external_frag,internal_frag,"
148	          // ... + 6 Observer-Spalten + pmc_available (die „+6" + Ehrlichkeits-Flag)
149	          "search_insert,search_lookup,search_hit,search_miss,search_erase,search_peak_occupancy,pmc_available,"
150	          "branch_misses,throughput_ops_per_sec\n";
151	    std::size_t const n = rows.size();
152	    for (std::size_t i = 0; i < n; ++i) {
153	        auto const&       m = rows[i];
154	        std::string const pid =
155	            (i < permutation_ids.size()) ? permutation_ids[i] : std::string{"row_"} + std::to_string(i);
156	        std::string const wl = (i < workload_used.size()) ? workload_used[i] : std::string{"default"};
157	        os << pid << ',' << m.fingerprint << ',' << static_cast<unsigned>(m.succeeded) << ',' << wl << ',' << m.op_count
158	           << ',' << m.total_cycles << ',' << m.cache_misses_l1 << ',' << m.cache_misses_l2 << ',' << m.cache_misses_l3
159	           << ',' << m.dtlb_misses << ',' << m.coherence_invalidations << ',' << m.energy_micro_joules << ','
160	           << m.bytes_allocated << ',' << m.bytes_in_use_peak << ',' << m.external_frag_milli << ','
161	           << m.internal_frag_milli << ',' << m.search_insert << ',' << m.search_lookup << ',' << m.search_hit << ','
162	           << m.search_miss << ',' << m.search_erase << ',' << m.search_peak_occupancy << ','
163	           << static_cast<unsigned>(m.pmc_available) << ',' << m.branch_misses << ',' << m.throughput_ops_per_sec
164	           << '\n';
165	    }
166	    return os.str();
167	}
