1	#pragma once
2	// V5-#26-SUBSTANZ — Mess-Quellen-Abstraktion für die 6 HW-Counter (PMC) des 16+6-Mess-POD.
3	//
4	// Re-Audit-Blocker 2: die „+6"-HW-Spalten (cache_misses L1/L2/L3, dtlb_misses, coherence_invalidations,
5	// energy) waren hartkodiert 0. Dieses Interface ist die SOFTWARE-Architektur, die sie speist — pluggable
6	// Mess-Quelle mit EHRLICHER Verfügbarkeits-Meldung (`available()`). Die REALEN Werte brauchen Intel PCM /
7	// RDPMC / RAPL-MSR (Vendor-Lib + Admin/MSR-Treiber auf der i7-1270P) = Beschaffung/Recht (P4, extern);
8	// bis dahin liefert `NullPmcSource` available()=false (statt stiller 0). Wenn die Hardware-Quelle verfügbar
9	// ist, ist sie ein Drop-in (eine weitere IPmcSource-Implementierung) — KEINE Änderung an POD/Pipeline/PDF.
10	//
11	// @doku docs/sessions/20260531-mess-abstraktion-cross-platform-architektur-plan.md (I2 PMC) + _v5_i8…/POD #50
12	
13	#include <cstdint>
14	#include <string_view>
15	
16	namespace comdare::cache_engine::builder {
17	
18	/// Die HW-Counter (Delta über ein Mess-Intervall) + Verfügbarkeits-Flag (= pmc_available im POD).
19	struct PmcCounters {
20	    std::uint64_t cache_misses_l1         = 0;
21	    std::uint64_t cache_misses_l2         = 0;
22	    std::uint64_t cache_misses_l3         = 0;
23	    std::uint64_t dtlb_misses             = 0;
24	    std::uint64_t branch_misses           = 0;
25	    std::uint64_t coherence_invalidations = 0;
26	    std::uint64_t energy_micro_joules     = 0;
27	    bool          available               = false; // false = NICHT real gemessen (ehrlich, kein Schein-0)
28	};
29	
30	/// Pluggable HW-Performance-Counter-Quelle. begin()→Op-Lauf→end() liefert das Counter-Delta.
31	class IPmcSource {
32	public:
33	    virtual ~IPmcSource()                                   = default;
34	    virtual void                           begin() noexcept = 0; ///< Zähler-Start (Intervall-Beginn)
35	    [[nodiscard]] virtual PmcCounters      end() noexcept   = 0; ///< Intervall-Ende → Delta (available je Quelle)
36	    [[nodiscard]] virtual bool             available() const noexcept = 0;
37	    [[nodiscard]] virtual std::string_view name() const noexcept      = 0;
38	};
39	
40	/// Default-Quelle, solange kein realer PMC angebunden ist: meldet EHRLICH „nicht verfügbar" (alle 0).
41	/// Ersetzt die früher hartkodierten 0-HW-Spalten durch ein explizites available=false (#26 / Re-Audit-Blocker 2).
42	class NullPmcSource final : public IPmcSource {
43	public:
44	    void                           begin() noexcept override {}
45	    [[nodiscard]] PmcCounters      end() noexcept override { return PmcCounters{}; } // available=false (Default)
46	    [[nodiscard]] bool             available() const noexcept override { return false; }
47	    [[nodiscard]] std::string_view name() const noexcept override { return "null-pmc (P4/HW-gated)"; }
48	};
49	
50	} // namespace comdare::cache_engine::builder
