9	namespace comdare::cache_engine::measurement {
10	
11	struct alignas(64) Context {
12	    std::uint64_t cache_lines_used = 0;
13	    std::uint64_t cache_misses_l1  = 0;
14	    std::uint64_t cache_misses_l2  = 0;
15	    std::uint64_t cache_misses_l3  = 0;
16	    std::uint64_t dtlb_misses      = 0;
17	    std::uint64_t branch_misses    = 0;
18	    std::uint64_t lookup_start_ns  = 0;
19	    std::uint64_t lookup_end_ns    = 0;
20	};
21	
22	// Primary template — Default-Hook (F-EXTRA-7), keine Wirkung
23	template <MeasurementCategory Cat, AlgoDetail Detail>
24	struct Measure {
25	    static constexpr void   at_lookup_begin(Context&) noexcept {}
26	    static constexpr void   at_lookup_end(Context&) noexcept {}
27	    static constexpr void   at_node_visit(std::uint64_t, Context&) noexcept {}
28	    static constexpr double extract(Context const&) noexcept { return 0.0; }
29	};
30	
31	// Beispiel-Spezialisierung: CLU x ART_NODE256 (Termin 7 / 03_uml_measurement §1)
32	template <>
33	struct Measure<MeasurementCategory::CLU, AlgoDetail::ART_NODE256> {
34	    static constexpr void at_lookup_begin(Context&) noexcept {}
35	    static constexpr void at_lookup_end(Context&) noexcept {}
36	    static constexpr void at_node_visit(std::uint64_t used_bytes, Context& ctx) noexcept {
37	        // CLU = effektiv genutzte Bytes pro Cache-Line (64 B)
38	        ctx.cache_lines_used += used_bytes / 64;
39	    }
40	    static constexpr double extract(Context const& ctx) noexcept { return ctx.cache_lines_used > 0 ? 1.0 : 0.0; }
41	};
42	
43	// Beispiel: LATENCY_MEAN x beliebig — generisch Lookup-Begin/End-Zeitstempel
44	template <AlgoDetail Detail>
45	struct Measure<MeasurementCategory::LATENCY_MEAN, Detail> {
46	    static constexpr void at_lookup_begin(Context& ctx) noexcept {
47	        // In echtem Build: rdtsc/clock_gettime; hier nur als Pflichtsignatur
48	        ctx.lookup_start_ns = 0;
49	    }
50	    static constexpr void   at_lookup_end(Context& ctx) noexcept { ctx.lookup_end_ns = 0; }
51	    static constexpr void   at_node_visit(std::uint64_t, Context&) noexcept {}
52	    static constexpr double extract(Context const& ctx) noexcept {
53	        return static_cast<double>(ctx.lookup_end_ns - ctx.lookup_start_ns);
54	    }
55	};
56	
57	// F-EXTRA-7 — HasMeasurement-Concept (Algo-spezifische Override-Erkennung)
58	template <typename AlgoTag, MeasurementCategory Cat>
59	concept HasMeasurement = requires {
60	    // Hat eine Spezialisierung von Measure<Cat, AlgoTag::detail>
61	    { Measure<Cat, AlgoTag::detail>::extract(std::declval<Context&>()) } -> std::convertible_to<double>;
62	};
63	
64	// F11 Trigger-Modus
65	enum class MeasurementTrigger : std::uint8_t {
66	    CONTINUOUS  = 0, // Builder-Modus, jeder Lookup
67	    SAMPLED_1_N = 1, // Production, default 1:1000
68	};
69	
70	class MeasurementHooks {
71	public:
72	    explicit MeasurementHooks(MeasurementTrigger t = MeasurementTrigger::CONTINUOUS, std::size_t sample_n = 1000)
73	        : trigger_(t), sample_n_(sample_n) {}
74	
75	    // Liefert true falls dieser Lookup gemessen werden soll
76	    [[nodiscard]] bool should_record() noexcept {
77	        if (trigger_ == MeasurementTrigger::CONTINUOUS) return true;
78	        ++sample_counter_;
79	        return (sample_counter_ % sample_n_) == 0;
80	    }
81	
82	    [[nodiscard]] MeasurementTrigger trigger() const noexcept { return trigger_; }
83	    [[nodiscard]] std::size_t        sample_n() const noexcept { return sample_n_; }
84	
85	private:
86	    MeasurementTrigger trigger_;
87	    std::size_t        sample_n_;
88	    std::size_t        sample_counter_ = 0;
89	};
90	
91	} // namespace comdare::cache_engine::measurement
