2	// IObserver + ObserverRegistry — F2 Push synchron mit Lambda-Tree-Filter
3	// Termin 7 / 02_uml_cache_engine §5
4	
5	#include <cache_engine/concepts/event.hpp>
6	
7	#include <map>
8	#include <vector>
9	
10	namespace comdare::cache_engine {
11	
12	class IObserver {
13	public:
14	    virtual ~IObserver() = default;
15	
16	    virtual void               on_event(Event const& event) noexcept  = 0;
17	    [[nodiscard]] virtual bool accepts(EventKind kind) const noexcept = 0;
18	};
19	
20	class ObserverRegistry {
21	public:
22	    void register_observer(ModuleId module, IObserver* observer) { module_observers_[module].push_back(observer); }
23	
24	    void unregister_module(ModuleId module) noexcept { module_observers_.erase(module); }
25	
26	    // F2 Push synchron: Algorithmus ruft direkt dispatch(event)
27	    void dispatch(Event const& event) noexcept {
28	        auto it = module_observers_.find(event.module_id);
29	        if (it == module_observers_.end()) return;
30	        for (IObserver* obs : it->second) {
31	            if (obs && obs->accepts(event.kind)) obs->on_event(event);
32	        }
33	    }
34	
35	    [[nodiscard]] std::size_t observer_count(ModuleId module) const noexcept {
36	        auto it = module_observers_.find(module);
37	        return it == module_observers_.end() ? 0 : it->second.size();
38	    }
39	
40	    void clear() noexcept { module_observers_.clear(); }
41	
42	private:
43	    std::map<ModuleId, std::vector<IObserver*>> module_observers_{};
44	};
45	
46	} // namespace comdare::cache_engine
