21	// ─────────────────────────────────────────────────────────────────────────────
22	// EmptyAxisSnapshot — Fallback fuer Achsen ohne statistics()
23	// ─────────────────────────────────────────────────────────────────────────────
24	
25	/// POD-Marker fuer Achsen die (noch) keine Statistics liefern.
26	/// Stufe-A-Wrappers ohne COMDARE_CE_ENABLE_STATISTICS bekommen diesen.
27	struct EmptyAxisSnapshot {
28	    // explicitly empty — standard_layout + trivially_copyable garantiert
29	    [[nodiscard]] constexpr bool operator==(EmptyAxisSnapshot const&) const noexcept { return true; }
30	};
31	
32	static_assert(std::is_standard_layout_v<EmptyAxisSnapshot>);
33	static_assert(std::is_trivially_copyable_v<EmptyAxisSnapshot>);
34	
35	// ─────────────────────────────────────────────────────────────────────────────
36	// ObservableAxis — Concept fuer Achsen mit statistics()
37	// ─────────────────────────────────────────────────────────────────────────────
38	
39	template <class A>
40	concept ObservableAxis = requires(A const& a) {
41	    typename A::snapshot_t;
42	    { a.statistics() } -> std::same_as<typename A::snapshot_t>;
43	};
44	
45	/// snapshot_of<A> — typeof(A::snapshot_t) wenn ObservableAxis, sonst EmptyAxisSnapshot.
46	template <class A>
47	struct snapshot_of {
48	    using type = std::conditional_t<
49	        ObservableAxis<A>,
50	        typename std::conditional_t<ObservableAxis<A>, A, void // ObservableAxis-Pfad: A::snapshot_t verfuegbar
51	                                    >::snapshot_t,             // (Achtung: nur gueltig wenn ObservableAxis<A>)
52	        EmptyAxisSnapshot>;
53	};
54	
55	// Specialization fuer Non-ObservableAxis — vermeidet snapshot_t-Lookup-Fehler
56	template <class A>
57	    requires(!ObservableAxis<A>)
58	struct snapshot_of<A> {
59	    using type = EmptyAxisSnapshot;
60	};
61	
62	template <class A>
63	using snapshot_of_t = typename snapshot_of<A>::type;
64	
65	// ─────────────────────────────────────────────────────────────────────────────
66	// snapshot_axis<A> — sample-Helper: extrahiert Snapshot oder Empty
67	// ─────────────────────────────────────────────────────────────────────────────
68	
69	template <class A>
70	[[nodiscard]] constexpr snapshot_of_t<A> snapshot_axis(A const& a) noexcept {
71	    if constexpr (ObservableAxis<A>) {
72	        return a.statistics();
73	    } else {
74	        return EmptyAxisSnapshot{};
75	    }
76	}
77	
78	// ─────────────────────────────────────────────────────────────────────────────
79	// ObserverAggregate<Composition> — 19 named Snapshot-Members (17 + queuing q1/q2)
80	// ─────────────────────────────────────────────────────────────────────────────
81	
82	/// ObserverAggregate ist ABI-stabiler Snapshot-Container pro Composition.
83	/// Pro Achse 1 Snapshot-Member (named nach Composition-using-Alias).
84	///
85	/// Pflicht-Eigenschaften:
86	/// - standard_layout (pro Member POD wenn alle Achsen-Snapshots POD sind)
87	/// - trivially_copyable (memcpy-faehig fuer ABI-Loader)
88	///
89	/// Aufbau zur Compile-Zeit:
90	///   ObserverAggregate<MyComposition> agg;
91	///   agg.search_algo_snapshot = my_anatomy.axis_search_algo_.statistics();
92	///   // ... 16 weitere ...
93	template <IsComposition Composition>
94	struct ObserverAggregate {
95	    snapshot_of_t<typename Composition::search_algo>        search_algo;
96	    snapshot_of_t<typename Composition::cache_traversal>    cache_traversal;
97	    snapshot_of_t<typename Composition::mapping>            mapping;
98	    snapshot_of_t<typename Composition::path_compression>   path_compression;
99	    snapshot_of_t<typename Composition::node_type>          node_type;
100	    snapshot_of_t<typename Composition::memory_layout>      memory_layout;
101	    snapshot_of_t<typename Composition::allocator>          allocator;
102	    snapshot_of_t<typename Composition::prefetch>           prefetch;
103	    snapshot_of_t<typename Composition::concurrency>        concurrency;
104	    snapshot_of_t<typename Composition::serialization>      serialization;
105	    snapshot_of_t<typename Composition::telemetry>          telemetry;
106	    snapshot_of_t<typename Composition::value_handle>       value_handle;
107	    snapshot_of_t<typename Composition::isa>                isa;
108	    snapshot_of_t<typename Composition::index_organization> index_organization;
109	    snapshot_of_t<typename Composition::io_dispatch>        io_dispatch;
110	    snapshot_of_t<typename Composition::migration_policy>   migration_policy;
111	    snapshot_of_t<typename Composition::filter>             filter;
112	    // Doc 30 §8.0: queuing q1/q2 als reguläre SA-Achsen (BufferStatistics / FlushPolicyStatistics
113	    // bei COMDARE_CE_ENABLE_STATISTICS; sonst EmptyAxisSnapshot via snapshot_of_t — wie alle anderen).
114	    snapshot_of_t<typename Composition::queuing_q1> queuing_q1;
115	    snapshot_of_t<typename Composition::queuing_q2> queuing_q2;
116	
117	    /// Anzahl der "echten" (nicht-Empty) Snapshots — Diagnose fuer Mess-Treiber.
118	    [[nodiscard]] static constexpr std::size_t observable_count() noexcept {
119	        std::size_t n = 0;
120	        if constexpr (ObservableAxis<typename Composition::search_algo>) ++n;
121	        if constexpr (ObservableAxis<typename Composition::cache_traversal>) ++n;
122	        if constexpr (ObservableAxis<typename Composition::mapping>) ++n;
123	        if constexpr (ObservableAxis<typename Composition::path_compression>) ++n;
124	        if constexpr (ObservableAxis<typename Composition::node_type>) ++n;
125	        if constexpr (ObservableAxis<typename Composition::memory_layout>) ++n;
126	        if constexpr (ObservableAxis<typename Composition::allocator>) ++n;
127	        if constexpr (ObservableAxis<typename Composition::prefetch>) ++n;
128	        if constexpr (ObservableAxis<typename Composition::concurrency>) ++n;
129	        if constexpr (ObservableAxis<typename Composition::serialization>) ++n;
130	        if constexpr (ObservableAxis<typename Composition::telemetry>) ++n;
131	        if constexpr (ObservableAxis<typename Composition::value_handle>) ++n;
132	        if constexpr (ObservableAxis<typename Composition::isa>) ++n;
133	        if constexpr (ObservableAxis<typename Composition::index_organization>) ++n;
134	        if constexpr (ObservableAxis<typename Composition::io_dispatch>) ++n;
135	        if constexpr (ObservableAxis<typename Composition::migration_policy>) ++n;
136	        if constexpr (ObservableAxis<typename Composition::filter>) ++n;
137	        if constexpr (ObservableAxis<typename Composition::queuing_q1>) ++n;
138	        if constexpr (ObservableAxis<typename Composition::queuing_q2>) ++n;
139	        return n;
140	    }
141	
142	    /// Total Achsen-Slot-Anzahl (Pflicht: 19 fuer Vollausbau — 17 Such-Achsen + queuing q1/q2, Doc 30 §8.0)
143	    [[nodiscard]] static constexpr std::size_t total_slots() noexcept { return 19; }
144	};
